INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-025', TRUE, '经济管理学院', '2024-11-22', '经济管理学院纪委召开纪委委员学习研讨会本网讯 11月21日上午，经济管理学院纪委在经管楼304会议室召开纪委委员学习研讨', '讲座培训', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 11月21日上午，经济管理学院纪委在经管楼304会议室召开纪委委员学习研讨会", "quote": "本网讯 11月21日上午，经济管理学院纪委在经管楼304会议室召开纪委委员学习研讨会"}]'::jsonb, '讲座培训：经济管理学院纪委召开纪委委员学习研讨会本网讯 11月21日上午，经济管理学院纪委', '[{"text": "本网讯 11月21日上午，经济管理学院纪委在经管楼304会议室召开纪委委员学习研讨会", "quote": "本网讯 11月21日上午，经济管理学院纪委在经管楼304会议室召开纪委委员学习研讨会"}]'::jsonb, '本网讯 11月21日上午，经济管理学院纪委在经管楼304会议室召开纪委委员学习研讨会。学院纪委全体委员参加会议，会议由学院党委副书记、纪委书记周涛主持。 会议集中学习了习近平总书记对社会工作作出的重要指示精神，围绕《中国共产党纪律处分条例》《中国共产党问责条例》《中国共产党党内监督条例》《纪检监察组织精准运用监督执纪“四种形态”的实施办法（试行）》及《中共安徽农业大学委员会运用监督执纪第一种形态工作实施细则（试行）》等内容进行了全面学习，并结合学习内容与学院当前重点工作监督进行了深入交流研讨。 会议强调，要不断加强', 'https://jgxy.ahau.edu.cn/info/1101/17916.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at